import json, os
from collections import Counter, defaultdict

VALID_ENTITY_TYPES = {"PER","ORG","LOC","TIME","NUM","MISC"}
ALIASES = {'PERSON':'PER','PEOPLE':'PER','ORGANIZATION':'ORG','ORGANISATION':'ORG',
           'LOCATION':'LOC','NUMBER':'NUM','NUMERICAL':'NUM','MISCELLANEOUS':'MISC'}
def norm(t):
    if not isinstance(t,str): return None
    n = ALIASES.get(t.strip().upper(), t.strip().upper())
    return n if n in VALID_ENTITY_TYPES else None
def s(x):
    return x.lower().strip() if isinstance(x,str) else ""

def analyze(path,label):
    cf=Counter(); tot=0; sizes=Counter(); docs=0
    for line in open(path):
        try: rec=json.loads(line)
        except: continue
        docs+=1
        po=rec.get("parsed_output") or {}
        ents=po.get("entities",[]) or []
        rels=po.get("relations",[]) or []
        mt=defaultdict(set)
        for e in ents:
            txt=s(e.get("text",""))
            nt=norm(e.get("type",""))
            if nt and txt: mt[txt].add(nt)
        for r in rels:
            h=s(r.get("head","")); t=s(r.get("tail",""))
            hn=norm(r.get("head_type","")); tn=norm(r.get("tail_type",""))
            if h and hn: mt[h].add(hn)
            if t and tn: mt[t].add(tn)
        for m,types in mt.items():
            if len(types)>1:
                tot+=1
                cf[tuple(sorted(types))]+=1
                sizes[len(types)]+=1
    print(f"\n=== {label} ===  docs={docs}, CF total={tot}, sizes={dict(sizes)}")
    for k,v in cf.most_common():
        print(f"  {' & '.join(k)}: {v}")

for p,lab in [
    ('/root/schema_semantic_constrained_ie/outputs/docred_full_s1.jsonl','DocRED full_s1 (Qwen)'),
